import{_ as a}from"./chunks/712f31a2f5a4af8ae0420094af456f19.Ca5y_-Uc.js";import{_ as e,c as d,a2 as r,o}from"./chunks/framework.BnrAgU0Y.js";const p=JSON.parse('{"title":"Langflow 中的辅助组件","description":"Langflow 中的辅助组件","frontmatter":{"title":"Langflow 中的辅助组件","description":"Langflow 中的辅助组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-helpers.md","filePath":"langflow/components-helpers.md"}'),h={name:"langflow/components-helpers.md"};function n(s,t,l,i,u,b){return o(),d("div",null,t[0]||(t[0]=[r('<h1 id="langflow-中的辅助组件" tabindex="-1">Langflow 中的辅助组件 <a class="header-anchor" href="#langflow-中的辅助组件" aria-label="Permalink to &quot;Langflow 中的辅助组件&quot;">​</a></h1><p>辅助组件提供实用功能，帮助管理数据、任务以及流中的其他组件。</p><h2 id="在流程中使用辅助组件" tabindex="-1">在流程中使用辅助组件 <a class="header-anchor" href="#在流程中使用辅助组件" aria-label="Permalink to &quot;在流程中使用辅助组件&quot;">​</a></h2><p>在 Langflow 中，聊天记录存储在本地 Langflow 表中使用 <code>LCBufferMemory</code>，或者连接到外部数据库中。</p><p>**Store Message（存储消息）<strong>辅助组件将聊天记录存储为<a href="./URL.html">数据</a>对象，而</strong>Message History（消息历史）**辅助组件则将聊天消息作为数据对象或字符串检索。</p><p>这个示例流程使用**Store Message（存储消息）<strong>和</strong>Chat Memory（聊天内存）**组件，从<a href="./URL.html">AstraDBChatMemory</a>组件中存储和检索聊天历史记录。</p><p><img src="'+a+'" alt="Sample Flow storing Chat Memory in AstraDB"></p><h2 id="batch-run-component" tabindex="-1">Batch Run Component <a class="header-anchor" href="#batch-run-component" aria-label="Permalink to &quot;Batch Run Component&quot;">​</a></h2><p>Batch Run 组件在一个 <a href="/concepts-objects#dataframe-object">DataFrame</a> 的文本列的每一行上运行一个语言模型，并返回一个新的 DataFrame，其中包含原始文本和模型的响应。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>类型</th><th>信息</th><th>必需</th></tr></thead><tbody><tr><td>model</td><td>Language Model</td><td>HandleInput</td><td>在此连接您的 LLM 组件的 &#39;Language Model&#39; 输出。</td><td>是</td></tr><tr><td>system_message</td><td>System Message</td><td>MultilineInput</td><td>针对 DataFrame 中所有行的多行系统指令。</td><td>否</td></tr><tr><td>df</td><td>DataFrame</td><td>DataFrameInput</td><td>要将其列（由 &#39;column_name&#39; 指定）视为文本消息的 DataFrame。</td><td>是</td></tr><tr><td>column_name</td><td>Column Name</td><td>StrInput</td><td>要视为文本消息的 DataFrame 列的名称。默认值=&#39;text&#39;。</td><td>是</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Method</th><th>Info</th></tr></thead><tbody><tr><td>batch_results</td><td>Batch Results</td><td>run_batch</td><td>一个包含两列的数据框：&#39;text_input&#39; 和 &#39;model_response&#39;。</td></tr></tbody></table><h2 id="创建列表" tabindex="-1">创建列表 <a class="header-anchor" href="#创建列表" aria-label="Permalink to &quot;创建列表&quot;">​</a></h2><p>该组件动态生成一个具有指定字段数量的记录。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>n_fields</td><td>字段数量</td><td>要添加到记录中的字段数量。</td></tr><tr><td>text_key</td><td>文本键</td><td>用作文本的键。</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>list</td><td>List</td><td>动态创建的包含指定字段数量的列表。</td></tr></tbody></table><h2 id="current-date" tabindex="-1">当前日期 <a class="header-anchor" href="#current-date" aria-label="Permalink to &quot;当前日期 {#current-date}&quot;">​</a></h2><p>当前日期组件返回所选时区的当前日期和时间。此组件提供了一种灵活的方法，可以在 Langflow 数据管道中获取特定时区的日期和时间信息。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>timezone</td><td>Timezone</td><td>选择当前日期和时间的时区。</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>current_date</td><td>Current Date</td><td>结果中的当前日期和时间，按照所选时区显示。</td></tr></tbody></table><h2 id="id-生成器" tabindex="-1">ID 生成器 <a class="header-anchor" href="#id-生成器" aria-label="Permalink to &quot;ID 生成器&quot;">​</a></h2><p>该组件用于生成唯一的 ID。</p><h3 id="inputs-2" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-2" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>unique_id</td><td>Value</td><td>生成的唯一ID。</td></tr></tbody></table><h3 id="outputs-2" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-2" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>id</td><td>ID</td><td>生成的唯一 ID。</td></tr></tbody></table><h2 id="message-history" tabindex="-1">Message history <a class="header-anchor" href="#message-history" aria-label="Permalink to &quot;Message history&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>在 Langflow 1.1 版本之前，该组件被称为 Chat Memory 组件。</p></div><p>该组件从 Langflow 表或外部内存中检索和管理聊天消息。</p><h3 id="inputs-3" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-3" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>memory</td><td>外部内存</td><td>从外部内存中检索消息。如果为空，将使用 Langflow 表。</td></tr><tr><td>sender</td><td>发送者类型</td><td>按发送者类型进行过滤。</td></tr><tr><td>sender_name</td><td>发送者名称</td><td>按发送者名称进行过滤。</td></tr><tr><td>n_messages</td><td>消息数量</td><td>要检索的消息数量。</td></tr><tr><td>session_id</td><td>会话 ID</td><td>聊天的会话 ID。如果为空，将使用当前会话 ID 参数。</td></tr><tr><td>order</td><td>顺序</td><td>消息的排序顺序。</td></tr><tr><td>template</td><td>模板</td><td>用于格式化数据的模板。可以包含键 <code>{text}</code>、<code>{sender}</code> 或消息数据中的任何其他键。</td></tr></tbody></table><h3 id="输出-1" tabindex="-1">输出 <a class="header-anchor" href="#输出-1" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>messages</td><td>Messages (Data)</td><td>检索到的消息作为数据对象。</td></tr><tr><td>messages_text</td><td>Messages (Text)</td><td>检索到的消息格式化为文本。</td></tr><tr><td>lc_memory</td><td>Memory</td><td>一个构造的 Langchain <a href="https://api.python.langchain.com/en/latest/memory/langchain.memory.buffer.ConversationBufferMemory.html" target="_blank" rel="noreferrer">ConversationBufferMemory</a> 对象。</td></tr></tbody></table><h2 id="message-store" tabindex="-1">消息存储 <a class="header-anchor" href="#message-store" aria-label="Permalink to &quot;消息存储 {#message-store}&quot;">​</a></h2><p>该组件将聊天消息或文本存储到 Langflow 表或外部存储中。</p><p>它在聊天系统中提供了管理消息存储和检索的灵活性。</p><h3 id="inputs-4" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-4" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>message</td><td>Message</td><td>要存储的聊天消息。（必需项）</td></tr><tr><td>memory</td><td>External Memory</td><td>用于存储消息的外部内存。如果为空，将使用 Langflow 表。</td></tr><tr><td>sender</td><td>Sender</td><td>消息的发送者。可以是 Machine 或 User。如果为空，将使用当前发送者参数。</td></tr><tr><td>sender_name</td><td>Sender Name</td><td>发送者的名称。可以是 AI 或 User。如果为空，将使用当前发送者参数。</td></tr><tr><td>session_id</td><td>Session ID</td><td>聊天的会话 ID。如果为空，将使用当前会话 ID 参数。</td></tr></tbody></table><h3 id="输出-2" tabindex="-1">输出 <a class="header-anchor" href="#输出-2" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>stored_messages</td><td>Stored Messages</td><td>当前消息添加后的存储消息列表。</td></tr></tbody></table><h2 id="结构化输出" tabindex="-1">结构化输出 <a class="header-anchor" href="#结构化输出" aria-label="Permalink to &quot;结构化输出&quot;">​</a></h2><p>此组件将 LLM（大语言模型）的响应转换为结构化数据格式。</p><h3 id="input" tabindex="-1">输入 <a class="header-anchor" href="#input" aria-label="Permalink to &quot;输入 {#input}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td><code>llm</code></td><td>语言模型</td><td>用于生成结构化输出的语言模型。</td></tr><tr><td><code>input_value</code></td><td>输入消息</td><td>供语言模型处理的输入消息。</td></tr><tr><td><code>schema_name</code></td><td>模式名称</td><td>为输出数据模式提供一个名称。</td></tr><tr><td><code>output_schema</code></td><td>输出模式</td><td>定义模型输出的结构和数据类型。</td></tr><tr><td><code>multiple</code></td><td>生成多个</td><td>如果模型需要生成一个输出列表而非单个输出，请设置为 True。</td></tr></tbody></table><h3 id="输出-3" tabindex="-1">输出 <a class="header-anchor" href="#输出-3" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>stored_messages</td><td>Stored Messages</td><td>基于定义的架构的结构化输出。</td></tr></tbody></table>',51)]))}const f=e(h,[["render",n]]);export{p as __pageData,f as default};
